import React, {useState} from "react";
import {motion, AnimatePresence} from "framer-motion";
import backgroundImage from "../assets/product.jpg";
import steak from "../assets/steak.png";
import seafood from "../assets/seafood.png";
import chicken from "../assets/chicken.png";
import potato from "../assets/potato.png";
import pasta from "../assets/italian.png";
import mexican from "../assets/mexican.png";
import spice from "../assets/spiceee.jpg";

import {useNavigate} from "react-router-dom";

function Product() {
  const [selectedId, setSelectedId] = useState(null);

  const categories = [
    {
      id: "1",
      name: "Steak",
      description: "MARINADE",
      image: steak,
      rating: 4,
      colorClass: "text-white",
      recipe: "Recipe for Steak: Ingredients and steps to prepare the steak.",
    },
    {
      id: "2",
      name: "Sea Food",
      description: "SEASONING",
      image: seafood,
      rating: 3,
      colorClass: "text-white",
      recipe:
        "Recipe for Sea Food: Ingredients and steps to prepare the sea food.",
    },
    {
      id: "3",
      name: "Chicken",
      description: "SEASONING",
      image: chicken,
      rating: 5,
      colorClass: "text-white",
      recipe:
        "Recipe for Chicken: Ingredients and steps to prepare the chicken.",
    },
    {
      id: "4",
      name: "Potato",
      description: "SEASONING",
      image: potato,
      rating: 2,
      colorClass: "text-white",
      recipe: "Recipe for Potato: Ingredients and steps to prepare the potato.",
    },
    {
      id: "5",
      name: "Italian",
      description: "SEASONING",
      image: pasta,
      rating: 4,
      colorClass: "text-white",
      recipe:
        "Recipe for Italian: Ingredients and steps to prepare the Italian dish.",
    },
    {
      id: "6",
      name: "Mexican Mix",
      description: "MARINADE",
      image: mexican,
      rating: 1,
      colorClass: "text-white",
      recipe:
        "Recipe for Mexican Mix: Ingredients and steps to prepare the Mexican mix.",
    },
  ];

  const handleCategoryClick = id => {
    setSelectedId(id);
  };

  const handleCloseOverlay = () => {
    setSelectedId(null);
  };

  const navigate = useNavigate();

  const handleViewMoreClick = () => {
    navigate("/all");
  };

  return (
    <div className="relative min-h-screen flex justify-center items-center">
      <div
        className="absolute inset-0 z-0"
        style={{
          backgroundImage: `url(${backgroundImage})`,
          backgroundAttachment: "fixed",
          backgroundSize: "cover",
          backgroundPosition: "center",
          backgroundRepeat: "no-repeat",
        }}
      ></div>

      <div className="absolute inset-0 bg-black opacity-50 z-0"></div>

      <div className="relative z-10 text-white text-center w-full max-w-7xl px-6">
        <h1 className="text-9xl pt-8" style={{fontFamily: "Aldhabi, serif"}}>
          Our Product
        </h1>

        <div className="bg-zinc-900 rounded-6xl shadow-4xl mx-auto mb-24 p-8">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {categories.map(category => (
              <motion.div
                key={category.id}
                layoutId={category.id}
                className="flex items-center p-4 rounded-lg cursor-pointer"
                onClick={() => handleCategoryClick(category.id)}
              >
                <img
                  src={category.image}
                  alt={category.name}
                  className="w-36 h-56 object-cover rounded-lg mr-4"
                />
                <div className="flex flex-col justify-center">
                  <motion.h2
                    layoutId={`title-${category.id}`}
                    className="text-4xl"
                    style={{fontFamily: "SilverForteGrungeGrunge"}}
                  >
                    {category.name}
                  </motion.h2>
                  <motion.h5
                    layoutId={`subtitle-${category.id}`}
                    className={`text-3xl ${category.colorClass}`}
                    style={{fontFamily: "Aldhabi, serif"}}
                  >
                    {category.description}
                  </motion.h5>
                </div>
              </motion.div>
            ))}
          </div>
        </div>

        <button
          onClick={handleViewMoreClick}
          className="absolute bottom-8 left-1/2 transform -translate-x-1/2 bg-orange-600 text-white py-3 px-6 rounded-full text-lg font-semibold hover:bg-zinc-900 transition duration-300 ease-in-out"
        >
          View More
        </button>
      </div>
      <AnimatePresence>
  {selectedId && (
    <motion.div
      layoutId={selectedId}
      className="fixed inset-0 z-50 flex flex-col justify-center items-center p-4 md:p-6"
      style={{
        backgroundImage: `url(${spice})`,
        backgroundSize: "cover", // Adjust the background size
        backgroundPosition: "center", // Center the background image
      }}
    >
      {/* Overlay div with a grey semi-transparent background */}
      <div
        className="absolute inset-0 bg-gray-800 opacity-50" // Apply grey background with transparency
        style={{
          zIndex: -1, // Make sure the overlay is behind the content
        }}
      ></div>

      <motion.button
        layoutId={`close-${selectedId}`}
        className="absolute top-4 right-4 text-3xl text-black"
        onClick={handleCloseOverlay}
      >
        &times;
      </motion.button>

      {categories
        .filter(category => category.id === selectedId)
        .map(category => (
          <React.Fragment key={category.id}>
            <motion.img
              layoutId={`image-${category.id}`}
              src={category.image}
              alt={category.name}
              className="w-80 h-80 object-contain rounded-lg mb-4"
            />
            <motion.p className="text-xl p-4">{category.recipe}</motion.p>
          </React.Fragment>
        ))}
    </motion.div>
  )}
</AnimatePresence>

    </div>
  );
}

export default Product;
